import React from 'react';
import DashboardLayout from './layouts/DashboardLayout';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import DashboardHome from './pages/DashboardHome';
import DynamicTablePage from './pages/DynamicTablePage';

function App() {
  return (
    <Router>
      <DashboardLayout>
        <Routes>
          <Route path="/" element={<DashboardHome />} />
          <Route path="/table/:slug" element={<DynamicTablePage />} />
        </Routes>
      </DashboardLayout>
    </Router>
  );
}

export default App;

@tailwind base;
@tailwind components;
@tailwind utilities;

body {
  font-family: 'Inter', sans-serif;
}

.dark-mode {
  background-color: #1a202c;
  color: #cbd5e0;
}

import React, { useEffect, useState } from 'react';
import Sidebar from '../components/Sidebar';

const DashboardLayout = ({ children }) => {
  return (
    <div className="flex">
      <Sidebar />
      <div className="ml-64 h-screen flex flex-col">
        <header className="h-16 fixed top-0 left-64 right-0 z-30 bg-gray-900 text-white flex items-center justify-between px-4">
          <h1 className="text-xl font-bold">ERP Admin Panel</h1>
        </header>
        <main className="flex-1 overflow-y-auto mt-16">
          {children}
        </main>
      </div>
    </div>
  );
};

export default DashboardLayout;

import axios from 'axios';

const instance = axios.create({
  baseURL: import.meta.env.VITE_ADMIN_BASE_URL,
  headers: {
    'Content-Type': 'application/json',
    'Authorization': 'API-KEY',
    'X-API-KEY': 'P-wkLyW3aBURDx6oSwtlhk33WQn8Q3VhIc'
  }
});

export default instance;

import React, { useEffect, useState } from 'react';
import axios from '../api/axios';
import { FaHome } from 'react-icons/fa';

const Sidebar = () => {
  const [menus, setMenus] = useState([]);

  useEffect(() => {
    const fetchMenus = async () => {
      const response = await axios.get(`/v3/menus?parent_id=c57eedc3-a954-4262-a0af-376c65b5a284&project-id=f1c4ae97-ee0f-4868-b4fc-1b26869ebc69`);
      setMenus(response.data?.data?.menus || []);
    };
    fetchMenus();
  }, []);

  return (
    <div className="h-screen w-64 fixed bg-gray-900 text-gray-300">
      <nav className="mt-10">
        {menus.map((menu) => (
          <a key={menu.id} href={menu.path} className="flex items-center p-2 hover:bg-blue-600 hover:text-white">
            <img src={menu.icon} className="w-5 h-5 filter invert brightness-200" onError={(e) => { e.currentTarget.style.display = 'none'; }} />
            <FaHome className="w-5 h-5" />
            <span className="ml-3 capitalize">{menu.name}</span>
          </a>
        ))}
      </nav>
    </div>
  );
};

export default Sidebar;

import React, { useEffect, useState } from 'react';
import axios from '../api/axios';

const DynamicTable = ({ slug }) => {
  const [fields, setFields] = useState([]);

  useEffect(() => {
    const fetchTableDetails = async () => {
      const response = await axios.post(`/v1/table-details/${slug}`, { data: {} });
      setFields(response.data?.data?.data?.fields || []);
    };
    fetchTableDetails();
  }, [slug]);

  return (
    <div className="table-container overflow-x-auto relative">
      <table className="min-w-full border-collapse">
        <thead className="bg-gray-800">
          <tr>
            {fields.map((field) => (
              <th key={field.id} className="sticky top-0 z-20 border border-gray-700 text-gray-200 uppercase text-xs font-bold tracking-wider">
                {field.name}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {/* Render table rows here */}
        </tbody>
      </table>
    </div>
  );
};

export default DynamicTable;

import React from 'react';

export const ElementLink = ({ value, disabled = true, required, placeholder = "", onBlur = () => {} }) => {
  const [innerValue, setInnerValue] = React.useState(value);
  return (
    <label className="flex items-center gap-2 border border-gray-700 p-2 rounded-md bg-gray-800 shadow-sm focus-within:ring-2 ring-blue-500">
      <input className="flex-1 outline-none bg-transparent text-white placeholder-gray-500" defaultValue={innerValue} disabled={disabled} required={required} placeholder={placeholder} onBlur={(e) => { onBlur(e); setInnerValue(e.target.value); }} />
      <a href={innerValue} className={"ml-2 px-3 py-1 text-xs font-bold text-white bg-blue-600 rounded-md hover:bg-blue-700 transition-colors " + (!innerValue ? "pointer-events-none opacity-50" : "") } target="_blank" rel="noreferrer">OPEN</a>
    </label>
  );
};

export const ElementText = ({ row = {}, value }) => {
  return <div className="text-sm text-gray-300 font-medium p-2">{value ?? row?.label}</div>;
};

import React from 'react';

const DashboardHome = () => {
  return (
    <div className="p-4">
      <h2 className="text-2xl font-bold text-gray-300">Welcome to the ERP Admin Panel</h2>
      <p className="mt-2 text-gray-400">Use the sidebar to navigate through the application.</p>
    </div>
  );
};

export default DashboardHome;

import React from 'react';
import { useParams } from 'react-router-dom';
import DynamicTable from '../components/DynamicTable';

const DynamicTablePage = () => {
  const { slug } = useParams();
  return (
    <div className="p-4">
      <h2 className="text-2xl font-bold text-gray-300 capitalize">{slug?.replace(/_/g, ' ')}</h2>
      <DynamicTable slug={slug} />
    </div>
  );
};

export default DynamicTablePage;
